import java.util.Scanner;
public class JInput4 {
	public static void main(String[] args) {
		// Khatwa 1: Qra' al-adad al-awwal alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil raqm sahih:");
		int num = scan.nextInt();
		// Khatwa 2: Atba' al-adad alladhi adkhalahu al-mustakhdim, thumma istaqbil al-a'dad al-muqbila ma dama al-mustakhdim yadkhol adadan laysa zawjan aw huwa aqal min 10; wa idha kana al-adad yalbi al-shart fatawaqqaf
		while ( num % 2 != 0 || num >= 10 ) {
			System.out.println("Al-raqm al-mudkhal huwa " + num);
			System.out.println("Adkhil raqm sahih:");
			num = scan.nextInt(); 
		}
		scan.close();
		System.out.println("Nihayat al-idkhal.");
	}
}
